    }
  },
  "grid": {
    "left": 15,
    "right": 15,
    "bottom": 30,
    "top": 100,
    "containLabel": true
  },
  "xAxis": {
    "type": "category",
    "data": [...new Set(COUNT_appsPerState_byAppStatus.data.map(item => item.clientName))].sort(),
    "axisLabel": {
      "fontSize": 14, // X-axis labels font size
      "interval": 0,
      "rotate": 45
    }
  },
  "yAxis": {
    "type": "value",
    "axisLabel": {
      "fontSize": 14 // Y-axis labels font size
    }
  },
  "series": (function() {
    const statuses = [...new Set(COUNT_appsPerState_byAppStatus.data.map(item => item.applicationStatus))].sort();
    const colors = ["#be5151", "#134463", "#95969d", "#fac858", "#73c0de", "#94959c"];

    return statuses.map((status, idx) => ({
      "name": status,
      "type": "bar",
      "stack": "total",
      "color": colors[idx % colors.length],
      "data": [...new Set(COUNT_appsPerState_byAppStatus.data.map(item => item.clientName))].sort().map(client => {
        const matchingRow = COUNT_appsPerState_byAppStatus.data.find(
          row => row.clientName === client && row.applicationStatus === status
        );
        return matchingRow ? matchingRow.CountOfappID : 0;
      }),
      "label": {
        "show": true,
        "position": "inside",
        "fontSize": 16, // Bar labels font size
        "formatter": function(params) {
          return params.value > 0 ? params.value : '';
        },
        "color": colors[idx % colors.length] === "#134463" ? "#fff" : "#000105"
      }
    }));
  })()
}
))(Chart2.chartType) }}
